import { createContext, useContext, useState, type ReactNode } from 'react'
import { useStore } from 'zustand'
import { createBearStore, type BearState } from './store'

type BearStore = ReturnType<typeof createBearStore>
const BearContext = createContext<BearStore | null>(null)

function BearProvider({ children }: { children: ReactNode }) {
  const [store] = useState(() => createBearStore())
  return <BearContext.Provider value={store}>{children}</BearContext.Provider>
}

function useBear<T>(selector: (state: BearState) => T): T {
  const store = useContext(BearContext)
  if (!store) throw new Error('Missing BearProvider')
  return useStore(store, selector)
}

export function Counter() {
  const bears = useBear((s) => s.bears)
  return <span>{bears}</span>
}

