import { create } from 'zustand'

type BearState = {
  bears: number
  addBear: () => void
}

type FishState = {
  fishes: number
  addFish: () => void
}

export const createBearSlice = (set: any): BearState => ({
  bears: 0,
  addBear: () => set((state: BearState) => ({ bears: state.bears + 1 })),
})

export const createFishSlice = (set: any): FishState => ({
  fishes: 0,
  addFish: () => set((state: FishState) => ({ fishes: state.fishes + 1 })),
})

const useBoundStore = create<BearState & FishState>()((...args) => ({
  ...createBearSlice(...args),
  ...createFishSlice(...args),
}))

export const useBearStore = <T>(selector: (state: BearState) => T) =>
  useBoundStore(selector as (state: BearState & FishState) => T)
export const useFishStore = <T>(selector: (state: FishState) => T) =>
  useBoundStore(selector as (state: BearState & FishState) => T)

export function App() {
  const bears = useBearStore((state) => state.bears)
  const addFish = useFishStore((state) => state.addFish)
  return <button onClick={addFish}>{bears}</button>
}

