import { createStore } from 'zustand/vanilla'
import { useStoreWithEqualityFn } from 'zustand/traditional'
import { shallow } from 'zustand/shallow'

type State = { bears: number; fish: number }
const store = createStore<State>(() => ({ bears: 0, fish: 0 }))

export function BearCounts() {
  const counts = useStoreWithEqualityFn(
    store,
    (state) => ({ bears: state.bears, fish: state.fish }),
    shallow,
  )
  return <div>{counts.bears} bears, {counts.fish} fish</div>
}

type BearState = {
  bears: number
  status: 'idle' | 'loading' | 'success' | 'error'
  error: string | null
  fetchBears: () => Promise<void>
}

export const useBearStore = create<BearState>()((set) => ({
  bears: 0,
  status: 'idle',
  error: null,
  fetchBears: async () => {
    set({ status: 'loading', error: null })
    try {
      const res = await fetch('/api/bears')
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      const data: { count: number } = await res.json()
      set({ bears: data.count, status: 'success' })
    } catch (error) {
      set({ status: 'error', error: String(error) })
    }
  },
}))

